CREATE TABLE "public"."clientes" (
  "id"               bigint                      GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nome"             text                        NOT NULL,
  "email"            text                        NOT NULL,
  "telefone"         text                        NOT NULL,
  "senha"            text                        NOT NULL,
  "aceito_lgpd"      boolean                     DEFAULT false,
  "data_aceite_lgpd" timestamp without time zone,
  "auth_user_id"     uuid,
  CONSTRAINT "ck_cli_email" CHECK ((email ~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'::text)),
  CONSTRAINT "ck_cli_lgpd" CHECK (((aceito_lgpd = false) OR (data_aceite_lgpd IS NOT NULL))),
  CONSTRAINT "ck_cli_telefone" CHECK ((telefone ~ '^[0-9]{10,11}$'::text)),
  CONSTRAINT "clientes_auth_user_id_fkey" FOREIGN KEY (auth_user_id) REFERENCES auth.users(id) ON DELETE SET NULL,
  CONSTRAINT "clientes_email_key" UNIQUE (email),
  CONSTRAINT "clientes_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."clientes"
  ENABLE ROW LEVEL SECURITY;

CREATE UNIQUE INDEX uq_clientes_auth_user_id ON public.clientes USING btree (auth_user_id)
  WHERE (auth_user_id IS NOT NULL);

CREATE TRIGGER trg_cli_lgpd
  BEFORE INSERT OR UPDATE OF aceito_lgpd ON public.clientes
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_lgpd();

CREATE POLICY "cliente_atualiza_proprio_perfil" ON "public"."clientes"
  FOR UPDATE
  TO "authenticated"
  USING ((auth_user_id = auth.uid()))
  WITH CHECK ((auth_user_id = auth.uid()));

CREATE POLICY "cliente_cria_proprio_perfil" ON "public"."clientes"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth_user_id = auth.uid()));

CREATE POLICY "cliente_le_proprio_perfil" ON "public"."clientes"
  FOR SELECT
  TO "authenticated"
  USING ((auth_user_id = auth.uid()));

REVOKE ALL ON SEQUENCE "public"."clientes_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clientes_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."clientes_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clientes_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."clientes_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clientes_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."clientes_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."clientes_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clientes" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clientes" TO "service_role";

COMMENT ON COLUMN "public"."clientes"."aceito_lgpd" IS 'Campo legado de compatibilidade; histórico detalhado em lgpd_consentimentos.';

COMMENT ON COLUMN "public"."clientes"."data_aceite_lgpd" IS 'Data do aceite atual do fluxo legado; histórico detalhado em lgpd_consentimentos.';

REVOKE ALL ON TABLE "public"."clientes" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clientes" TO "postgres";
